figures.source:
#set page(width: 16cm, height: auto, margin: 6pt)
#set text(font: "New Computer Modern", size: 9pt)
#set par(leading: 0.5em, justify: false)

#let accent = rgb("#2b5797")

// Family styles: one accent colour; in greyscale the families are told apart by line style
#let fam = (
  A: (ink: accent, tint: accent.lighten(84%), dash: none, w: 0.9pt),
  B: (ink: luma(45), tint: luma(212), dash: "dashed", w: 0.85pt),
  C: (ink: luma(80), tint: luma(240), dash: "dotted", w: 1.2pt),
)

#let fstroke(f) = {
  let d = fam.at(f)
  if d.dash == none {
    (paint: d.ink, thickness: d.w, cap: "round")
  } else {
    (paint: d.ink, thickness: d.w, cap: "round", dash: d.dash)
  }
}

#let cellbody(body, w, bold: false) = block(width: w, inset: (x: 3.5pt, y: 4pt), {
  set text(size: 8pt, weight: if bold { "bold" } else { "regular" })
  set par(leading: 0.42em)
  body
})

#let hatch(w, h, step: 3.6pt, paint: luma(180)) = box(width: w, height: h, clip: true, {
  let n = int(calc.ceil((w + h) / step)) + 2
  for i in range(n) {
    let x = i * step
    place(top + left, line(start: (x, 0pt), end: (x - h, h), stroke: 0.45pt + paint))
  }
})

#let seat = (
  A: ([Claude Opus 5.5], [author]),
  B: ([GPT-6.2 Sol], [checker; referee seats (rotated between rounds)]),
  C: ([Gemini 4 Carbon], [challenger; verifier; referee seats (rotated between rounds)]),
)

#let seatbox(f, w) = block(
  width: w, inset: (x: 5pt, y: 5.5pt), radius: 4pt,
  fill: fam.at(f).tint, stroke: fstroke(f),
  {
    set text(size: 8.5pt)
    set par(leading: 0.42em)
    text(weight: "bold", fill: if f == "A" { accent } else { black }, seat.at(f).at(0))
    [ — ]
    seat.at(f).at(1)
  },
)

#let tag(w) = block(width: w, inset: (x: 4pt, y: 3pt), radius: 2pt, fill: luma(236), {
  set text(size: 8pt, fill: luma(50))
  set par(leading: 0.4em)
  [own command-line client · no tools · no delegation · strict JSON answers]
})

#let band(w) = block(width: w, inset: (x: 7pt, y: 5pt), radius: 2pt, fill: luma(244), stroke: 0.6pt + luma(110), {
  set text(size: 8.5pt)
  set align(center)
  [*production journal:* every prompt and answer stored in the paper folder; a rerun replays them without calling a model]
})

#let legend(w) = block(width: w, {
  set text(size: 8pt)
  set par(leading: 0.45em)
  let sw(f) = box(width: 9pt, height: 7pt, baseline: 1pt, fill: fam.at(f).tint, stroke: 0.4pt + luma(140))
  sw("A")
  h(1.5pt)
  sw("B")
  h(1.5pt)
  sw("C")
  [ shaded cell: names a family; an arrow runs from that family's seat to its row.]
  h(8pt)
  box(width: 9pt, height: 7pt, baseline: 1pt, stroke: 0.4pt + luma(140), hatch(9pt, 7pt))
  [ hatched cell: any family other than those that produced the work.]
})

#let cols = (2.35cm, 2.85cm, 2.95cm, 2.1cm)
#let header = ([Decision], [Work produced by], [Judged by], [Constraint checked in code])
#let rows = (
  (
    ([choose among reformulations], none),
    ([family that proposed the three directions], none),
    ([a different family], "H"),
    ([judge $!=$ proposer], none),
  ),
  (
    ([accept a citation], none),
    ([checker (GPT-6.2 Sol) proposes a verbatim abstract passage], "B"),
    ([verifier (Gemini 4 Carbon)], "C"),
    ([verifier $!=$ checker], none),
  ),
  (
    ([accept an answer to a referee finding], none),
    ([author (Claude Opus 5.5)], "A"),
    ([the referee seat that raised the finding (GPT-6.2 Sol or Gemini 4 Carbon)], "BC"),
    ([referee $!=$ author], none),
  ),
  (
    ([settle a finding disputed after 3 answers], none),
    ([author and referee in dispute], none),
    ([adjudicator: the remaining family], "H"),
    ([adjudicator $in.not$ #"{author, referee}"], none),
  ),
  (
    ([reconcile final text with claim ledger], none),
    ([author (Claude Opus 5.5)], "A"),
    ([a family other than the author's], "H"),
    ([reconciler $!=$ author], none),
  ),
)

// (row index, family, vertical position within the row) for each arrow
#let entries = (
  (1, "B", 0.24), (1, "C", 0.68),
  (2, "B", 0.2), (2, "C", 0.56), (2, "A", 0.84),
  (4, "A", 0.5),
)

#let Wt = 15.55cm
#let Lw = 4.25cm
#let G = 1.05cm

#context {
  let x0 = Lw
  let x1 = Lw + G
  let tw = cols.sum()
  let colx = ()
  let acc = x1
  for c in cols {
    colx.push(acc)
    acc = acc + c
  }

  let hh = calc.max(..range(4).map(i => measure(cellbody(header.at(i), cols.at(i), bold: true)).height))
  let nat = rows.map(r => calc.max(26pt, ..range(4).map(i => measure(cellbody(r.at(i).at(0), cols.at(i))).height)))

  let order = ("B", "C", "A")
  let bh = order.map(f => measure(seatbox(f, Lw)).height)
  let tag-in = 8pt
  let th = measure(tag(Lw - tag-in)).height
  let tgap = 2.5pt
  let blocks = bh.map(b => b + tgap + th)
  let top0 = hh + 6pt
  let mingap = 9pt
  let left-need = top0 + blocks.sum() + 2 * mingap

  let lg = legend(tw)
  let lg-h = measure(lg).height
  let lg-gap = 6pt
  let table-need = hh + nat.sum() + lg-gap + lg-h

  let H = calc.max(left-need, table-need)
  let extra = (H - table-need) / rows.len()
  let rh = nat.map(n => n + extra)
  let gap = (H - top0 - blocks.sum()) / (order.len() - 1)

  let rowy = ()
  let yy = hh
  for r in rh {
    rowy.push(yy)
    yy = yy + r
  }
  let tbottom = yy

  let by = ()
  let ys = top0
  for k in range(order.len()) {
    by.push(ys)
    ys = ys + blocks.at(k) + gap
  }
  let ysrc = (:)
  for k in range(order.len()) {
    ysrc.insert(order.at(k), by.at(k) + bh.at(k) / 2)
  }

  let lane = (A: x0 + 19pt, B: x0 + 19pt, C: x0 + 9pt)
  let tgt(f) = entries.filter(e => e.at(1) == f).map(e => rowy.at(e.at(0)) + rh.at(e.at(0)) * e.at(2))

  let bd = band(Wt)
  let bd-h = measure(bd).height
  let total = H + 8pt + bd-h

  box(width: Wt, height: total, {
    // cell backgrounds and text
    for (ri, r) in rows.enumerate() {
      for (ci, cell) in r.enumerate() {
        let (body, kind) = cell
        let x = colx.at(ci)
        let y = rowy.at(ri)
        let w = cols.at(ci)
        let h = rh.at(ri)
        if kind == "H" {
          place(top + left, dx: x, dy: y, hatch(w, h))
        } else if kind == "BC" {
          place(top + left, dx: x, dy: y, rect(width: w, height: h / 2, fill: fam.B.tint, stroke: none))
          place(top + left, dx: x, dy: y + h / 2, rect(width: w, height: h / 2, fill: fam.C.tint, stroke: none))
        } else if kind != none {
          place(top + left, dx: x, dy: y, rect(width: w, height: h, fill: fam.at(kind).tint, stroke: none))
        }
        let shown = if kind == "H" { highlight(fill: white, extent: 1.2pt, body) } else { body }
        let cb = cellbody(shown, w)
        let ch = measure(cb).height
        place(top + left, dx: x, dy: y + (h - ch) / 2, cb)
      }
    }

    // header
    for ci in range(4) {
      let cb = cellbody(header.at(ci), cols.at(ci), bold: true)
      let ch = measure(cb).height
      place(top + left, dx: colx.at(ci), dy: (hh - ch) / 2, cb)
    }

    // table rules
    let hl(y, s) = place(top + left, line(start: (x1, y), end: (x1 + tw, y), stroke: s))
    hl(0pt, 0.9pt + luma(30))
    hl(hh, 0.6pt + luma(30))
    for ri in range(1, rows.len()) { hl(rowy.at(ri), 0.4pt + luma(170)) }
    hl(tbottom, 0.9pt + luma(30))
    for ci in range(1, 4) {
      place(top + left, line(start: (colx.at(ci), 0pt), end: (colx.at(ci), tbottom), stroke: 0.4pt + luma(195)))
    }
    place(top + left, line(start: (x1, 0pt), end: (x1, tbottom), stroke: 0.4pt + luma(160)))
    place(top + left, line(start: (x1 + tw, 0pt), end: (x1 + tw, tbottom), stroke: 0.4pt + luma(160)))

    // left panel heading
    place(top + left, line(start: (0pt, 0pt), end: (Lw, 0pt), stroke: 0.9pt + luma(30)))
    place(top + left, line(start: (0pt, hh), end: (Lw, hh), stroke: 0.6pt + luma(30)))
    place(top + left, dx: 0pt, dy: 0pt, block(width: Lw, height: hh, inset: (x: 3.5pt),
      align(left + horizon, text(size: 8pt, weight: "bold")[Seats in this run])))

    // seat boxes and their tags
    for k in range(order.len()) {
      let f = order.at(k)
      place(top + left, dx: 0pt, dy: by.at(k), seatbox(f, Lw))
      place(top + left, dx: tag-in, dy: by.at(k) + bh.at(k) + tgap, tag(Lw - tag-in))
    }

    // arrows from each seat to the rows where it holds a named cell
    let route(f, halo: false) = {
      let s0 = ysrc.at(f)
      let lx = lane.at(f)
      let ts = tgt(f)
      let st = fstroke(f)
      let lo = calc.min(s0, ..ts)
      let hi = calc.max(s0, ..ts)
      place(top + left, line(start: (x0, s0), end: (lx, s0), stroke: st))
      place(top + left, line(start: (lx, lo), end: (lx, hi), stroke: st))
      for t in ts {
        if halo {
          place(top + left, line(start: (lx + 2.5pt, t), end: (x1 - 6pt, t), stroke: 3.4pt + white))
        }
        place(top + left, line(start: (lx, t), end: (x1 - 4pt, t), stroke: st))
        place(top + left, polygon(fill: fam.at(f).ink, stroke: none,
          (x1 - 4.8pt, t - 2.4pt), (x1, t), (x1 - 4.8pt, t + 2.4pt)))
      }
    }
    route("B")
    route("A")
    route("C", halo: true)

    // legend and journal band
    place(top + left, dx: x1, dy: tbottom + lg-gap, lg)
    place(top + left, dx: 0pt, dy: H + 8pt, bd)
  })
}
